  transformers: { before: [context => root => ts.visitNode(root, function visit(node) {
    if (ts.isImportDeclaration(node)) return undefined;
    return ts.visitEachChild(node, visit, context);
  })] }
}).outputText.replace('export {};', '');
const fixture = { id: 66, projectId: 7, issueNo: 'SYNTHETIC-066', issueTitle: 'Synthetic issue', priority: 'HIGH', issueStatus: 'OPEN', discoveredAt: '2026-09-07T09:00:00', ownerId: 9, ownerName: 'Test owner', drillRoundId: 10, drillRoundName: 'Test round', issueDescription: 'Description\nline two', analysisContent: 'Analysis', actionContent: 'Action', followUpContent: 'Follow up', rowVersion: 3 };
const exposed = 'issues,members,rounds,total,page,pageSize,keyword,priority,status,loading,saving,error,forbidden,drawerOpen,drawerMode,selectedIssue,editingIssue,form,formErrors,confirmingClose,openDetail,openIssue,closeDrawer,saveIssue,removeIssue,load,applyFilter,changePage,changePageSize';
function setup({ mobile = false, manage = true } = {}) {
  const calls = [], messages = [];
  const hooks = {};
  let confirmResult = 'accept';
  let saveError = false;
  let listError = null;
  let saveWait = null;
  let listHook = null;
  const response = data => ({ data: { data } });
