    onMounted: fn => { hooks.mount = fn; }, onBeforeUnmount: fn => { hooks.unmount = fn; },
    defineProps: () => ({ projectId: 7 }), useAuthStore: () => ({ hasPermission: () => manage }),
    window: { matchMedia: () => ({ matches: mobile }) },
    apiErrorMessage: (_, fallback) => fallback,
    ElMessage: { success: m => messages.push(['success', m]), error: m => messages.push(['error', m]) },
    ElMessageBox: { confirm: async () => { calls.push(['confirm']); if (confirmResult !== 'accept') throw confirmResult; } },
    listReleaseOperationsIssues: async params => { calls.push(['list', params]); if (listHook) return listHook(params); if (listError) throw listError; return response({ records: [{ ...fixture }], total: 25 }); },
    listReleaseOperationMemberOptions: async id => { calls.push(['members', id]); return response([]); },
    listReleaseDrills: async id => { calls.push(['rounds', id]); return response([]); },
    createReleaseOperationsIssue: async (...args) => { calls.push(['create', ...args]); if (saveWait) await saveWait; if (saveError) throw Error('synthetic'); return response({ ...fixture }); },
    updateReleaseOperationsIssue: async (...args) => { calls.push(['update', ...args]); if (saveWait) await saveWait; if (saveError) throw Error('synthetic'); return response({ ...fixture }); },
    deleteReleaseOperationsIssue: async (...args) => { calls.push(['delete', ...args]); return response(null); }
  };
  const api = new Function(...Object.keys(env), output + '\nreturn {' + exposed + ', viewMode: typeof viewMode === "undefined" ? null : viewMode };')(...Object.values(env));
