(async () => {
  const passed = [];
  const check = (name, fn) => { fn(); passed.push(name); };
  let t = setup(), a = t.api;
  await a.load();
  check('Load retains server records and project parameters', () => { assert.equal(a.total.value,25); assert.equal(t.calls[0][1].projectId,7); });
