  check('Cancel discard keeps drawer and input', () => { assert.equal(a.drawerOpen.value,true); assert.equal(a.form.issueTitle,'Changed draft'); });
  t.confirm('accept'); await a.closeDrawer();
  check('Explicit discard closes drawer', () => assert.equal(a.drawerOpen.value,false));
  a.openIssue(); a.form.issueNo = ' '; a.form.issueTitle = ' ';
  await a.saveIssue();
  check('Blank required values cannot save and have inline errors', () => { assert.ok(a.formErrors.value.issueNo); assert.ok(a.formErrors.value.issueTitle); assert.equal(t.calls.filter(c => c[0] === 'create').length,0); });
  a.form.issueNo='SYNTHETIC'; a.form.issueTitle='Synthetic'; a.form.issueStatus='CLOSED';
  await a.saveIssue();
  check('CLOSED requires timestamp', () => { assert.ok(a.formErrors.value.closedAt); assert.equal(t.calls.filter(c => c[0] === 'create').length,0); });
  a.form.closedAt='2026-09-07T10:00:00'; t.failSave(true); await a.saveIssue();
  check('Failed save retains draft and unlocks retry', () => { assert.equal(a.drawerOpen.value,true); assert.equal(a.form.issueTitle,'Synthetic'); assert.equal(a.saving.value,false); assert.equal(t.messages.at(-1)[0],'error'); });
  t.failSave(false); a.page.value=2; a.keyword.value='Synthetic'; a.priority.value='HIGH'; await a.saveIssue();
  check('Create uses original payload and preserves query context', () => { assert.equal(a.drawerOpen.value,false); assert.equal(a.page.value,2); assert.equal(a.keyword.value,'Synthetic'); const c=t.calls.filter(c=>c[0]==='create').at(-1); assert.equal(c[1],7); assert.equal(c[2].closedAt,'2026-09-07T10:00:00'); });
  a.openIssue(fixture); await a.saveIssue();
  check('Edit keeps id, project and concurrency version', () => { const c=t.calls.find(c=>c[0]==='update'); assert.equal(c[1],7); assert.equal(c[2],66); assert.equal(c[3].rowVersion,3); assert.equal(c[3].drillRoundId,10); });
  t.confirm('cancel'); const errorCount=t.messages.filter(m=>m[0]==='error').length; await a.removeIssue(fixture);
  check('Delete cancellation makes no delete request or error', () => { assert.equal(t.calls.filter(c=>c[0]==='delete').length,0); assert.equal(t.messages.filter(m=>m[0]==='error').length,errorCount); });
  t.confirm('close'); await a.removeIssue(fixture);
  check('Closing delete confirmation makes no request', () => assert.equal(t.calls.filter(c=>c[0]==='delete').length,0));
  t.confirm('accept'); await a.removeIssue(fixture);
  check('Confirmed delete retains rowVersion and project', () => assert.deepEqual(t.calls.find(c=>c[0]==='delete'),['delete',7,66,3]));
  t=setup({manage:false}); a=t.api; await a.load(); a.openDetail(fixture); a.openIssue(fixture); await a.saveIssue(); await a.removeIssue(fixture);
  check('Read-only viewing does not call maintenance APIs', () => { assert.equal(a.drawerMode.value,'detail'); assert.deepEqual(t.calls.map(c=>c[0]),['list']); });
  t=setup(); a=t.api; a.openIssue(fixture); let release; t.waitSave(new Promise(resolve=>{ release=resolve; }));
  const pending=a.saveIssue(); await a.saveIssue(); await a.closeDrawer();
  check('Saving blocks duplicate submit and drawer dismissal', () => { assert.equal(a.saving.value,true); assert.equal(a.drawerOpen.value,true); assert.equal(t.calls.filter(c=>c[0]==='update').length,1); });
  release(); await pending;
  t=setup(); a=t.api; t.failList({response:{status:403}}); await a.load();
  check('403 is distinct from generic error', () => { assert.equal(a.forbidden.value,true); assert.equal(a.issues.value.length,0); });
  t.failList(Error('offline')); await a.load();
  check('Load error is recoverable and resets loading', () => { assert.equal(a.forbidden.value,false); assert.ok(a.error.value); assert.equal(a.loading.value,false); });
  t.failList(null); await a.load();
  check('Retry clears error and restores records', () => { assert.equal(a.error.value,''); assert.equal(a.issues.value.length,1); });
  t=setup(); a=t.api; let finishOld; t.listWith(()=>new Promise(resolve=>{finishOld=resolve;})); const oldLoad=a.load();
  t.listWith(null); await a.load(); finishOld({data:{data:{records:[],total:0}}}); await oldLoad;
  check('Out-of-order response cannot overwrite latest query', () => assert.equal(a.total.value,25));
  t.hooks.unmount(); const count=t.calls.length; await a.load();
  check('Unmounted project cannot start another load', () => assert.equal(t.calls.length,count));
  if (a.viewMode) {
    t=setup(); a=t.api; await a.load(); a.page.value=2; a.pageSize.value=20; a.keyword.value='needle'; a.priority.value='HIGH'; a.status.value='OPEN';
    const before=JSON.stringify([a.issues.value,a.total.value,a.page.value,a.pageSize.value,a.keyword.value,a.priority.value,a.status.value]); const count=t.calls.length;
    check('Desktop initially selects list', () => assert.equal(a.viewMode.value,'list'));
    a.viewMode.value='cards'; a.viewMode.value='list';
    check('View switching preserves query, rows and pagination without requests', () => { assert.equal(JSON.stringify([a.issues.value,a.total.value,a.page.value,a.pageSize.value,a.keyword.value,a.priority.value,a.status.value]),before); assert.equal(t.calls.length,count); });
