    check('Both modes expose details and guarded maintenance', () => { assert.ok(descriptor.template.content.includes('v-for="issue in issues"')); assert.ok(descriptor.template.content.includes('openDetail(issue)')); assert.ok(descriptor.template.content.includes('openDetail(scope.row)')); });
  }
  check('One drawer replaces old dialog and details render escaped text', () => { assert.equal((descriptor.template.content.match(/<el-drawer\b/g)||[]).length,1); assert.ok(!descriptor.template.content.includes('<el-dialog')); assert.ok(!descriptor.template.content.includes('v-html')); });
  console.log(JSON.stringify({passed:passed.length,checks:passed,limitations:['Node state/contract checks with synthetic mocked APIs only','No DOM, screenshots, real server writes or independent browser acceptance']},null,2));
